  "inlineSchema": "// ============================================\n// Prisma Schema — TurbineIQ PostgreSQL Database\n// ============================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// =============================================\n// ENUMS\n// =============================================\n\nenum Role {\n  STUDENT\n  TEACHER\n}\n\nenum MachineType {\n  WIND_TURBINE\n  STEAM_TURBINE\n  GAS_TURBINE\n  HYDRO_TURBINE\n  MOTOR\n  GENERATOR\n  PUMP\n  COMPRESSOR\n}\n\n// =============================================\n// USER MODEL\n// =============================================\n\nmodel User {\n  id          String   @id @default(uuid())\n  email       String   @unique\n  password    String\n  name        String\n  role        Role     @default(STUDENT)\n  institution String?\n  department  String?\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relations\n  projects    Project[]\n  teams       Team[]       @relation(\"TeamMembers\")\n  taughtTeams Team[]       @relation(\"TeamTeacher\")\n  assignments Assignment[]\n  submissions Submission[]\n\n  @@map(\"users\")\n}\n\n// =============================================\n// PROJECT MODEL\n// =============================================\n\nmodel Project {\n  id          String      @id @default(uuid())\n  name        String\n  description String?\n  machineType MachineType\n  status      String      @default(\"active\") // active, completed, archived\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  // Relations\n  userId      String\n  user        User              @relation(fields: [userId], references: [id], onDelete: Cascade)\n  trials      SimulationTrial[]\n  submissions Submission[]\n\n  @@map(\"projects\")\n}\n\n// =============================================\n// SIMULATION TRIAL MODEL (Trial & Error)\n// =============================================\n\nmodel SimulationTrial {\n  id          String  @id @default(uuid())\n  trialNumber Int\n  trialName   String?\n\n  // Input parameters — stored as JSON for flexibility across machine types\n  // e.g., { bladeCount: 3, pitchAngle: 12, rotorDiameter: 80, windSpeed: 10 }\n  parameters Json\n\n  // Output results\n  efficiencyPercent Float?\n  powerOutput       Float?\n  specificResults   Json? // Machine-specific detailed results\n\n  notes     String?\n  createdAt DateTime @default(now())\n\n  // Relations\n  projectId String\n  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)\n\n  @@map(\"simulation_trials\")\n}\n\n// =============================================\n// MACHINE CATALOG (Manufacturers & Models)\n// =============================================\n\nmodel MachineCatalog {\n  id           String      @id @default(uuid())\n  machineType  MachineType\n  manufacturer String\n  modelName    String\n  type         String? // e.g., \"Onshore Wind Turbine\"\n  capacity     String? // e.g., \"6.2 MW\"\n  keyFeatures  String?\n\n  @@map(\"machine_catalog\")\n}\n\n// =============================================\n// CAD MODELS (3D Model Links)\n// =============================================\n\nmodel CadModel {\n  id          String      @id @default(uuid())\n  machineType MachineType\n  component   String // e.g., \"Horizontal Axis Wind Turbine\"\n  platform    String // e.g., \"GrabCAD\"\n  fileFormat  String? // e.g., \"STEP/IGES\"\n  directLink  String\n\n  @@map(\"cad_models\")\n}\n\n// =============================================\n// RESEARCH PAPERS\n// =============================================\n\nmodel ResearchPaper {\n  id           String  @id @default(uuid())\n  domain       String // e.g., \"Wind\", \"Steam\"\n  title        String\n  authors      String?\n  year         Int?\n  journal      String?\n  doiLink      String?\n  keyTakeaways String?\n\n  @@map(\"research_papers\")\n}\n\n// =============================================\n// RESOURCE LINKS (Master Data Pack)\n// =============================================\n\nmodel ResourceLink {\n  id           String  @id @default(uuid())\n  machineType  String // Original type from CSV: \"Wind\", \"Steam\", etc.\n  resourceName String\n  directLink   String\n  fileType     String?\n  category     String? // Dataset, Manual, 3D Model, Research\n  priority     Int?\n  folder       String?\n  pgTable      String?\n  purpose      String?\n\n  @@map(\"resource_links\")\n}\n\n// =============================================\n// LMS MODELS (Professor Portal)\n// =============================================\n\nmodel Team {\n  id        String   @id @default(uuid())\n  name      String\n  joinCode  String   @unique\n  teacherId String\n  createdAt DateTime @default(now())\n\n  teacher     User         @relation(\"TeamTeacher\", fields: [teacherId], references: [id])\n  members     User[]       @relation(\"TeamMembers\")\n  assignments Assignment[] @relation(\"TeamAssignments\")\n\n  @@map(\"teams\")\n}\n\nmodel Assignment {\n  id          String      @id @default(uuid())\n  title       String\n  description String\n  machineType MachineType\n  dueDate     DateTime?\n  teacherId   String\n  createdAt   DateTime    @default(now())\n\n  teacher     User         @relation(fields: [teacherId], references: [id])\n  teams       Team[]       @relation(\"TeamAssignments\")\n  submissions Submission[]\n\n  @@map(\"assignments\")\n}\n\nenum SubmissionStatus {\n  PENDING\n  GRADED\n}\n\nmodel Submission {\n  id           String           @id @default(uuid())\n  assignmentId String\n  studentId    String\n  projectId    String?\n  status       SubmissionStatus @default(PENDING)\n  score        Float?\n  feedback     String?\n  fileUrl      String?\n  submittedAt  DateTime         @default(now())\n  gradedAt     DateTime?\n\n  assignment Assignment @relation(fields: [assignmentId], references: [id])\n  student    User       @relation(fields: [studentId], references: [id])\n  project    Project?   @relation(fields: [projectId], references: [id])\n\n  @@map(\"submissions\")\n}\n",
